			/**
			 * 사업자등록번호 포매팅
			 * @param {Stirng} value 사업자등록번호 값
			 * @param {Stirng} type 마스킹여부 숫자
			 */
			function brnoFormatter (value, type){
			    
			    if (value == null || value == "") {
			        return "";
			    }
			    
			    var regex = /[^0-9]/g; // 숫자가 아닌 문자열을 선택하는 정규식
			    var num = value.replace(regex, "");
			    
			    var formatNum = '';
			    
			    try {
			        
			//        if (num.length == 10) {
			            if (type == 0) {
			                formatNum = num.replace(/(\d{3})(\d{2})(\d{5})/, '$1-****-$3');
			            } else {
			                formatNum = num.replace(/(\d{3})(\d{2})(\d{5})/, '$1-$2-$3');
			            }
			//        }
			    } catch (e) {
			        formatNum = num;
			        console.log(e);
			    }
			    return formatNum;    
			}

			/**
			 * 사업자등록번호 입력 후 사업자구분코드 셋팅
			 * 공동코드 (사업자구분코드(BZMN_SE_CD))
			    001: 개인과세사업자                           / 사업자등록번호 가운데 두자리 : 01 ~ 79
			    002: 개인면세사업자                           / 사업자등록번호 가운데 두자리 : 90 ~ 99
			    003: 법인이아닌종교단체                       / 사업자등록번호 가운데 두자리 : 89
			    004: 아파트관리사무소, 다단계판매업자 등      / 사업자등록번호 가운데 두자리 : 80
			    005: 영립법인의 본점                          / 사업자등록번호 가운데 두자리 : 81, 86
			    006: 비영리법인, 법인격없는 사단이나 재단 등  / 사업자등록번호 가운데 두자리 : 82
			    007: 국가, 지방자치단체 등                    / 사업자등록번호 가운데 두자리 : 83
			    008: 외국법인                                 / 사업자등록번호 가운데 두자리 : 84 
			    009: 영리법인의 지점                          / 사업자등록번호 가운데 두자리 : 85
			 * @param {String} brno
			 */
			function settingBzmnDcd(brno){
			    
			    /* 사업자구분코드 BZMN_SE_CD(공통코드명)*/
			    
			    // 000-00-000000
			    if(ValueUtil.isNull(brno)) return false;
			    
			    var regex = /[^0-9]/g; // 숫자가 아닌 문자열을 선택하는 정규식
			    var num = brno.replace(regex, "");
			    
			    var settingNum = num;    
			    
			    var bzmnDcd = num.substr(3, 2);                 /* 개인법인 구분코드 2자리*/
			    var seCode  = ValueUtil.fixNumber(bzmnDcd);     /* 범위확인위해 숫자변경*/
			    
			    if (seCode >= 01 && seCode <= 79){
			//        console.log("001/개인사업자");
			        settingNum = '001';
			    }else if(seCode >= 90 && seCode <= 99){
			//        console.log("002/개인면세사업자");
			        settingNum = '002';
			    }else if(seCode == 89){
			//        console.log("003/법인이아닌종교단체");
			        settingNum = '003';
			    }else if(seCode == 80){
			//        console.log("004/아파트관리사무소, 다단계판매업자 등");
			        settingNum = '004';
			    }else if(seCode == 81 || seCode == 86){
			//        console.log("005/영립법인의 본점");
			        settingNum = '005';
			    }else if(seCode == 82){
			//        console.log("006/비영리법인, 법인격없는 사단이나 재단 등");
			        settingNum = '006';
			    }else if(seCode == 83){
			//        console.log("007/국가, 지방자치단체 등");
			        settingNum = '007';
			    }else if(seCode == 84){
			//        console.log("008/외국법인");
			        settingNum = '008';
			    }else if(seCode == 85){
			//        console.log("009/영립법인의 지점");
			        settingNum = '009';
			    }
			    
			    return settingNum;
			}

